"use client";
import dynamic from "next/dynamic";
import { useScrollProgress } from "@/hooks/useScrollProgress";

const RoadScene = dynamic(() => import("@/components/canvas/RoadScene"), { ssr: false });

// ── Math helpers ──────────────────────────────────────────────────────────────
function norm(p: number, a: number, b: number) {
  return Math.max(0, Math.min(1, (p - a) / (b - a)));
}
function eo(t: number) { return 1 - (1 - t) ** 3; }
function e(p: number, a: number, b: number) { return eo(norm(p, a, b)); }
function fade(p: number, a: number, b: number, c: number, d: number) {
  if (p < a || p >= d) return 0;
  if (p < b) return (p - a) / (b - a);
  if (p <= c) return 1;
  return 1 - (p - c) / (d - c);
}

// Style builders — only opacity + transform (GPU composited)
const up  = (t: number, d = 28) => ({ opacity: t, transform: `translateY(${(1-t)*d}px)` } as React.CSSProperties);
const lft = (t: number, d = 50) => ({ opacity: t, transform: `translateX(${(1-t)*-d}px)` } as React.CSSProperties);
const rgt = (t: number, d = 50) => ({ opacity: t, transform: `translateX(${(1-t)*d}px)` } as React.CSSProperties);
const sc  = (t: number)         => ({ opacity: t, transform: `scale(${0.86 + t * 0.14})` } as React.CSSProperties);

// ── Data ──────────────────────────────────────────────────────────────────────
const VALORES   = ["Responsabilidad", "Integridad", "Experiencia", "Adaptabilidad"];
const SERVICIOS = [
  { title: "SG-SST",             desc: "Ciclo PHVA · Decreto 1072/2015" },
  { title: "Outsourcing",        desc: "Medicina, psicología, ergonomía" },
  { title: "Gestión Ambiental",  desc: "ISO 14001:2015" },
  { title: "Asesoría Legal",     desc: "Riesgos laborales y seguridad social" },
  { title: "Auditorías",         desc: "ISO 45001 · 14001 · 9001" },
  { title: "Capacitaciones",     desc: "Psicosocial, químico, mecánico" },
  { title: "Gestión del Riesgo", desc: "Tareas críticas y emergencias" },
];
const MARCAS = [
  { name: "Submarca 1", desc: "Descripción de la primera submarca",  accent: "#ff8d2b" },
  { name: "Submarca 2", desc: "Descripción de la segunda submarca",  accent: "#0546f2" },
];
const CONTACTO_INFO = [
  { label: "Email",     value: "info@consalud.com.co" },
  { label: "Teléfono",  value: "+57 (1) 234-5678" },
  { label: "Ciudad",    value: "Bogotá, Colombia" },
];

// ── Sections meta ─────────────────────────────────────────────────────────────
// 5 sections × 0.20 of scroll each (total height: 600vh)
const SECTIONS = [
  { num: "01", label: "Inicio" },
  { num: "02", label: "Nosotros" },
  { num: "03", label: "Servicios" },
  { num: "04", label: "Marcas" },
  { num: "05", label: "Contacto" },
];

export default function HeroPage() {
  const p = useScrollProgress();

  // ── Section opacities (fade in → hold → fade out within each 0.20 band) ────
  const heroO  = p < 0.14 ? 1 : p < 0.20 ? 1 - (p - 0.14) / 0.06 : 0;
  const nosO   = fade(p, 0.20, 0.24, 0.36, 0.40);
  const servO  = fade(p, 0.40, 0.44, 0.56, 0.60);
  const marcO  = fade(p, 0.60, 0.64, 0.76, 0.80);
  const contO  = fade(p, 0.80, 0.84, 0.97, 1.01);

  // Section opacities array (for watermarks + labels)
  const sectionO = [heroO, nosO, servO, marcO, contO];

  // ── Local build progressions ──────────────────────────────────────────────
  const hL = norm(p, 0.00, 0.14);
  const nL = norm(p, 0.20, 0.39);
  const sL = norm(p, 0.40, 0.59);
  const mL = norm(p, 0.60, 0.79);
  const cL = norm(p, 0.80, 0.97);

  // ── Hero build ──
  const hBadge = e(hL, 0.00, 0.18);
  const hW1    = e(hL, 0.10, 0.32);
  const hW2    = e(hL, 0.26, 0.50);
  const hW3    = e(hL, 0.42, 0.65);
  const hSub   = e(hL, 0.58, 0.80);
  const hCta   = e(hL, 0.72, 0.95);
  const hCue   = 1 - norm(p, 0.14, 0.22);

  // ── Nosotros build ──
  const nLabel = e(nL, 0.00, 0.14);
  const nTitle = e(nL, 0.10, 0.28);
  const nText  = e(nL, 0.24, 0.44);
  const nLine  = norm(nL, 0.38, 0.58);
  const nS1    = e(nL, 0.42, 0.58);
  const nS2    = e(nL, 0.50, 0.66);
  const nS3    = e(nL, 0.58, 0.74);
  const nC     = [e(nL,0.62,0.78), e(nL,0.67,0.83), e(nL,0.72,0.88), e(nL,0.77,0.93)];
  const years    = Math.round(nS1 * 27);
  const services = Math.round(nS2 * 7);

  // ── Servicios build ──
  const sLabel = e(sL, 0.00, 0.14);
  const sTitle = e(sL, 0.08, 0.24);
  const sCards = SERVICIOS.map((_, i) => e(sL, 0.20 + i * 0.09, 0.36 + i * 0.09));

  // ── Marcas build ──
  const mLabel = e(mL, 0.00, 0.18);
  const mTitle = e(mL, 0.12, 0.32);
  const mC     = [e(mL, 0.28, 0.56), e(mL, 0.44, 0.72)];

  // ── Contacto build ──
  const cLabel = e(cL, 0.00, 0.18);
  const cTitle = e(cL, 0.12, 0.32);
  const cSub   = e(cL, 0.26, 0.48);
  const cInfo  = CONTACTO_INFO.map((_, i) => e(cL, 0.40 + i * 0.14, 0.58 + i * 0.14));
  const cCta   = e(cL, 0.72, 0.95);

  return (
    <div className="relative" style={{ height: "600vh" }}>
      <div className="sticky top-0 h-screen overflow-hidden">

        {/* ── WebGL Road background ─────────────────────────────────────────── */}
        <RoadScene progress={p} className="absolute inset-0 w-full h-full" />

        {/* ── Section watermark ─────────────────────────────────────────────── */}
        {SECTIONS.map(({ num }, i) => (
          <div
            key={num}
            className="absolute right-8 bottom-16 font-extrabold leading-none pointer-events-none select-none text-[180px]"
            style={{ opacity: sectionO[i] * 0.035, color: "#ffffff" }}
          >
            {num}
          </div>
        ))}

        {/* ── Section label bottom-left ─────────────────────────────────────── */}
        {SECTIONS.map(({ num, label }, i) => (
          <div key={num} className="absolute bottom-8 left-8 z-20 pointer-events-none" style={{ opacity: sectionO[i] }}>
            <p className="text-[10px] tracking-[0.3em] uppercase text-white/25">
              {num} / 05 — {label}
            </p>
          </div>
        ))}

        {/* ── Nav dots ─────────────────────────────────────────────────────── */}
        <div className="absolute right-6 top-1/2 -translate-y-1/2 z-30 flex flex-col gap-3">
          {SECTIONS.map(({ label }, i) => {
            const from = i * 0.20;
            const to   = (i + 1) * 0.20;
            const active = p >= from && p < to;
            return (
              <div key={label} className="group flex items-center gap-2 justify-end">
                <span className="text-xs text-white/40 opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap">
                  {label}
                </span>
                <div
                  className="rounded-full transition-all duration-300"
                  style={{
                    width:  active ? 10 : 6,
                    height: active ? 10 : 6,
                    background: active ? "#ff8d2b" : "rgba(255,255,255,0.2)",
                  }}
                />
              </div>
            );
          })}
        </div>

        {/* ── SCENE 1: HERO ─────────────────────────────────────────────────── */}
        <div className="absolute inset-0 flex items-center z-10 pointer-events-none" style={{ opacity: heroO }}>
          <div className="max-w-6xl mx-auto px-8 w-full">

            <div style={up(hBadge, 16)}>
              <p className="text-[11px] font-semibold uppercase tracking-[0.28em] text-[#ff8d2b] mb-8">
                Aliado Vital SST · Bogotá · Desde 1998
              </p>
            </div>

            <h1 className="font-extrabold leading-[0.90] mb-10" style={{ fontSize: "clamp(52px, 8vw, 100px)" }}>
              <span className="block overflow-hidden">
                <span className="block" style={up(hW1, 44)}>Tu socio</span>
              </span>
              <span className="block overflow-hidden">
                <span
                  className="block text-transparent bg-clip-text"
                  style={{ ...up(hW2, 44), backgroundImage: "linear-gradient(90deg, #ff8d2b 0%, #0546f2 100%)" }}
                >
                  estratégico
                </span>
              </span>
              <span className="block overflow-hidden">
                <span className="block text-white/85" style={up(hW3, 44)}>en SST.</span>
              </span>
            </h1>

            <p className="text-xl text-white/45 max-w-lg leading-relaxed mb-12" style={up(hSub)}>
              Protegemos a tu equipo con soluciones a la medida —&nbsp;sin
              improvisaciones, con respaldo académico y experiencia real.
            </p>

            <div
              className="flex flex-col sm:flex-row gap-4"
              style={{ ...up(hCta), pointerEvents: hCta > 0.5 ? "auto" : "none" }}
            >
              <button
                className="px-8 py-3.5 rounded-full font-semibold text-[#05123e] hover:brightness-110 transition-all cursor-pointer border-none"
                style={{ background: "#ff8d2b" }}
              >
                Ver servicios
              </button>
              <button className="px-8 py-3.5 rounded-full border border-white/20 hover:border-[#ff8d2b]/50 text-white/60 hover:text-white font-semibold transition-all cursor-pointer bg-transparent">
                Conocer Consalud
              </button>
            </div>
          </div>

          <div
            className="absolute bottom-10 left-1/2 -translate-x-1/2 flex flex-col items-center gap-2 text-white/25 text-xs"
            style={{ opacity: hCue }}
          >
            <span className="tracking-[0.3em] uppercase text-[10px]">Scroll</span>
            <div className="w-px h-10 animate-pulse" style={{ background: "linear-gradient(to bottom, #ff8d2b55, transparent)" }} />
          </div>
        </div>

        {/* ── SCENE 2: NOSOTROS ─────────────────────────────────────────────── */}
        <div className="absolute inset-0 flex items-center z-10 pointer-events-none" style={{ opacity: nosO }}>
          <div className="max-w-6xl mx-auto px-8 w-full grid grid-cols-1 md:grid-cols-2 gap-16">

            <div>
              <div style={lft(nLabel)}>
                <p className="text-[11px] font-semibold uppercase tracking-[0.28em] text-[#ff8d2b] mb-4">Quiénes somos</p>
              </div>
              <div style={lft(nTitle, 40)}>
                <h2 className="text-4xl md:text-5xl font-extrabold text-white leading-tight mb-6">
                  Expertos que simplifican la normativa SST
                </h2>
              </div>
              <div style={lft(nText, 30)}>
                <p className="text-white/45 text-lg leading-relaxed mb-10">
                  Desde 1998 en Bogotá, acompañamos a empresas colombianas
                  con un modelo a la medida — equipo interdisciplinar,
                  respaldo académico y cero improvisaciones.
                </p>
              </div>

              <div className="relative h-px mb-8" style={{ background: "rgba(255,255,255,0.07)" }}>
                <div
                  className="absolute top-0 left-0 h-full"
                  style={{ width: `${nLine * 100}%`, background: "linear-gradient(90deg, #ff8d2b, #0546f2)" }}
                />
              </div>

              <div className="grid grid-cols-3 gap-6">
                {[
                  { val: `${years}+`, label: "años de experiencia",    t: nS1 },
                  { val: `${services}`, label: "servicios especializados", t: nS2 },
                  { val: "100%",      label: "soluciones a la medida", t: nS3 },
                ].map(({ val, label, t }) => (
                  <div key={label} style={up(t, 16)}>
                    <p className="text-3xl font-extrabold text-[#ff8d2b]">{val}</p>
                    <p className="text-white/30 text-xs mt-1 leading-snug">{label}</p>
                  </div>
                ))}
              </div>
            </div>

            <div>
              <div style={rgt(nLabel)}>
                <p className="text-[11px] font-semibold uppercase tracking-[0.28em] text-[#ff8d2b] mb-4">Nuestros valores</p>
              </div>
              <div className="grid grid-cols-2 gap-4">
                {VALORES.map((v, i) => (
                  <div
                    key={v}
                    className="p-5 rounded-2xl border border-white/10"
                    style={{ ...sc(nC[i]), background: "rgba(5,18,62,0.75)" }}
                  >
                    <div className="w-2 h-2 rounded-full bg-[#ff8d2b] mb-3" />
                    <p className="text-white font-semibold text-sm">{v}</p>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>

        {/* ── SCENE 3: SERVICIOS ────────────────────────────────────────────── */}
        <div className="absolute inset-0 flex items-center z-10 pointer-events-none" style={{ opacity: servO }}>
          <div className="max-w-6xl mx-auto px-8 w-full">
            <div style={up(sLabel)}>
              <p className="text-[11px] font-semibold uppercase tracking-[0.28em] text-[#ff8d2b] mb-3">Lo que hacemos</p>
            </div>
            <div style={up(sTitle, 32)}>
              <h2 className="text-4xl md:text-5xl font-extrabold text-white mb-10">Nuestros servicios</h2>
            </div>

            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
              {SERVICIOS.map((s, i) => (
                <div
                  key={s.title}
                  className="p-5 rounded-2xl border border-white/10"
                  style={{ ...sc(sCards[i]), background: "rgba(5,18,62,0.82)" }}
                >
                  <div className="h-px mb-4" style={{ width: `${sCards[i] * 28}px`, background: "#ff8d2b" }} />
                  <p className="text-white font-bold text-sm mb-1">{s.title}</p>
                  <p className="text-white/35 text-xs leading-snug">{s.desc}</p>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* ── SCENE 4: MARCAS ───────────────────────────────────────────────── */}
        <div className="absolute inset-0 flex items-center z-10 pointer-events-none" style={{ opacity: marcO }}>
          <div className="max-w-6xl mx-auto px-8 w-full">
            <div className="text-center mb-14">
              <div style={up(mLabel)}>
                <p className="text-[11px] font-semibold uppercase tracking-[0.28em] text-[#ff8d2b] mb-3">Nuestras marcas</p>
              </div>
              <div style={up(mTitle, 32)}>
                <h2 className="text-4xl md:text-5xl font-extrabold text-white">Un universo de soluciones</h2>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 max-w-3xl mx-auto">
              {MARCAS.map(({ name, desc, accent }, i) => (
                <div
                  key={name}
                  className="p-10 rounded-3xl border"
                  style={{
                    ...(i === 0 ? lft(mC[0]) : rgt(mC[1])),
                    borderColor: `${accent}33`,
                    background: "rgba(5,18,62,0.92)",
                  }}
                >
                  <div className="h-0.5 mb-6" style={{ width: 36, background: accent }} />
                  <h3 className="text-2xl font-bold text-white mb-3">{name}</h3>
                  <p className="text-white/35 text-sm mb-8 leading-relaxed">{desc}</p>
                  <span className="text-sm font-semibold" style={{ color: accent }}>Explorar →</span>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* ── SCENE 5: CONTACTO ─────────────────────────────────────────────── */}
        <div className="absolute inset-0 flex items-center z-10 pointer-events-none" style={{ opacity: contO }}>
          <div className="max-w-6xl mx-auto px-8 w-full grid grid-cols-1 md:grid-cols-2 gap-16 items-center">

            {/* Left: copy + CTA */}
            <div>
              <div style={lft(cLabel)}>
                <p className="text-[11px] font-semibold uppercase tracking-[0.28em] text-[#ff8d2b] mb-4">Trabajemos juntos</p>
              </div>
              <div style={lft(cTitle, 40)}>
                <h2 className="text-4xl md:text-5xl font-extrabold text-white leading-tight mb-6">
                  Protege a tu equipo hoy
                </h2>
              </div>
              <div style={lft(cSub, 30)}>
                <p className="text-white/45 text-lg leading-relaxed mb-10">
                  Agenda una consulta gratuita y descubre cómo Consalud
                  puede simplificar tu SST — sin compromisos.
                </p>
              </div>

              <div
                className="flex flex-col sm:flex-row gap-4"
                style={{ ...up(cCta), pointerEvents: cCta > 0.5 ? "auto" : "none" }}
              >
                <button
                  className="px-8 py-3.5 rounded-full font-semibold text-[#05123e] hover:brightness-110 transition-all cursor-pointer border-none"
                  style={{ background: "#ff8d2b" }}
                >
                  Contáctanos
                </button>
                <button className="px-8 py-3.5 rounded-full border border-white/20 hover:border-[#ff8d2b]/50 text-white/60 hover:text-white font-semibold transition-all cursor-pointer bg-transparent">
                  Ver servicios
                </button>
              </div>
            </div>

            {/* Right: contact info cards */}
            <div className="flex flex-col gap-4">
              {CONTACTO_INFO.map(({ label, value }, i) => (
                <div
                  key={label}
                  className="p-5 rounded-2xl border border-white/10 flex items-center gap-5"
                  style={{ ...rgt(cInfo[i]), background: "rgba(5,18,62,0.80)" }}
                >
                  <div className="w-2 h-2 rounded-full flex-shrink-0" style={{ background: "#ff8d2b" }} />
                  <div>
                    <p className="text-[10px] tracking-[0.25em] uppercase text-white/30 mb-0.5">{label}</p>
                    <p className="text-white font-semibold text-sm">{value}</p>
                  </div>
                </div>
              ))}
            </div>

          </div>
        </div>

      </div>
    </div>
  );
}
